FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 089: revolves about a profile's own edge, circles lofted along a quarter circle. Generated by tools/fixtures/gen-batch-089.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

// Each face of a body: its area and its surface's type.
function faceProbe(context is Context, body is Query) returns array
{
    var out = [];
    for (var face in evaluateQuery(context, qOwnedByBody(body, EntityType.FACE)))
    {
        var entry = { "area" : roundToPrecision(evArea(context, { "entities" : face }) / millimeter ^ 2, 6) };
        try
        {
            entry["type"] = evSurfaceDefinition(context, { "face" : face, "returnBSplinesAsOther" : true }).surfaceType;
        }
        catch (error)
        {
            entry["type"] = "failed";
        }
        out = append(out, entry);
    }
    return out;
}

// revolve: batch 084 c005's trapezoid revolved about its own edge on z, the edge found by a point on it
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(s1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(10, 0) * millimeter });
    skLineSegment(s1, "l2", { "start" : vector(10, 0) * millimeter, "end" : vector(6, 20) * millimeter });
    skLineSegment(s1, "l3", { "start" : vector(6, 20) * millimeter, "end" : vector(0, 20) * millimeter });
    skLineSegment(s1, "l4", { "start" : vector(0, 20) * millimeter, "end" : vector(0, 0) * millimeter });
    skSolve(s1);
    const axisQuery = qContainsPoint(qCreatedBy(id + "s1", EntityType.EDGE), vector(0, 0, 10) * millimeter);
    revolve(context, id + "base", { "entities" : qSketchRegion(id + "s1"), "axis" : axisQuery, "fullRevolve" : true });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)), "axis" : size(evaluateQuery(context, axisQuery)) };
}

