// loft: batch 074 c006's circles lofted along the quarter circle with 2 sections
export function c006(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(20, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s1, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 20) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(s2, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 3 * millimeter });
    skSolve(s2);
    const path = newSketchOnPlane(context, id + "path", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skArc(path, "a1", { "start" : vector(20, 0) * millimeter, "mid" : vector(14.142136, 14.142136) * millimeter, "end" : vector(0, 20) * millimeter });
    skSolve(path);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "s1") }, { "sheetProfileEntities" : qSketchRegion(id + "s2") }], "addSections" : true, "spine" : qCreatedBy(id + "path", EntityType.EDGE), "sectionCount" : 2 });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)) };
}

